import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Runtime integration recovery — 2026-10-14","description":"","frontmatter":{},"headers":[],"relativePath":"feature/system-maintenance/runtime-integration-recovery/spec.md","filePath":"feature/system-maintenance/runtime-integration-recovery/spec.md"}'),s={name:"feature/system-maintenance/runtime-integration-recovery/spec.md"};function o(r,e,c,l,d,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="runtime-integration-recovery-—-2026-10-14" tabindex="-1">Runtime integration recovery — 2026-10-14 <a class="header-anchor" href="#runtime-integration-recovery-—-2026-10-14" aria-label="Permalink to &quot;Runtime integration recovery — 2026-10-14&quot;">​</a></h1><h2 id="objective-and-scope" tabindex="-1">Objective and scope <a class="header-anchor" href="#objective-and-scope" aria-label="Permalink to &quot;Objective and scope&quot;">​</a></h2><p>Restore existing Mail, Content Writing and Content Request integrations after synchronising branches. This is a bugfix, not new BA. References: <code>../content-task-workflow/3-6-10-content-writting-view/spec.md</code>, <code>../content-task-workflow/3-6-32-send-email-via-template/spec.md</code>, <code>../authentication/3-2-2-sign-in-with-email/spec.md</code>, and <code>../../BA/05-content-task-workflow.md</code>.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ol><li>Mail&#39;s existing PostgreSQL migration supplies all five missing tables. Fresh init contains the same definitions. Preserve existing application data; do not initialise Mongo or send test email.</li><li>Editor WebSocket passes through Gateway with existing downstream JWT and Task membership checks intact. Reconnect uses the latest authenticated session, not a captured expired token. Preserve the existing Yjs pending-update queue.</li><li>HTTP 401 uses the existing rotating-cookie refresh flow, at most one retry per request, including concurrent requests. Invalid refresh responses reject; never resolve a protected request with undefined data.</li><li>Content Request data endpoints reject unsuccessful/malformed envelopes. Valid empty lists remain valid. Do not mask failures with mock/empty data.</li><li>Emoji search/categories work without cross-origin public API access. Dataset is versioned and locally served with its licence. Failed loads have a working retry; no CORS proxy or security bypass.</li><li>Do not recreate a successful Campaign deployment. Only the explicit deployment-not-found business code is an expected absent deployment; unrelated 404s remain errors.</li></ol><h2 id="ui-states" tabindex="-1">UI states <a class="header-anchor" href="#ui-states" aria-label="Permalink to &quot;UI states&quot;">​</a></h2><p>Existing visual design remains. Emoji loading/error/empty/success states use semantic theme tokens, keyboard-accessible controls and parallel <code>editor.emojiPicker.*</code> keys in <code>src/i18n/locales/{vi,en}/editor.json</code>. Initial content loading failures must be visible/retryable, without discarding edits on transient reconnect failures.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>No BA changes, Task phase-1 stash restoration, seed accounts, shared Mongo changes, new Campaign deployments, commits/pushes or changes to specialised content workflows.</p>',9)])])}const h=t(s,[["render",o]]);export{m as __pageData,h as default};
